package main
import (
  "fmt"
  "errors"
)
func f() error {
  return errors.New("wrapped error")
}
func main() {
  err := f()
  if errors.Is(err, errors.New("wrapped error")) {
    fmt.Println("match")
  } else {
    fmt.Println("no match")
  }
}

